            //
            aOrbiterE = ((aWandererC + RotL64(aScatter, 13U)) + 0x9DE5DEC938F6FC1AULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterF = (aWandererD + RotL64(aCross, 47U)) + 0x4BF944F4B85F9B79ULL;
            aOrbiterK = ((aWandererH + RotL64(aPrevious, 4U)) + 0x37CEA5490E137016ULL) + aTwistOrbiterAssignSaltB[((aIndex + 7U)) & S_SALT1];
