            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x545CF1295C2C0ECDULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0x9EEDD9E0DBA586E9ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 15U)) & S_SALT1];
