            aWandererD = aWandererD + ((RotL64(aPrevious, 35U) + aOrbiterB) + RotL64(aOrbiterD, 37U));
            aWandererG = aWandererG ^ (((RotL64(aCross, 41U) + RotL64(aOrbiterK, 3U)) + aOrbiterG) + aTwistWandererUpdateSaltB[((aIndex + 27U)) & S_SALT1]);
