            aWandererC = aWandererC ^ (((RotL64(aPrevious, 5U) + aOrbiterD) + RotL64(aOrbiterG, 60U)) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aIngress, 19U) + aOrbiterI) + RotL64(aOrbiterF, 53U)) + RotL64(aCarry, 23U));
