            aOrbiterG = (aWandererG + RotL64(aCross, 27U)) + 0x414C61C7C6D7C1B4ULL;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 60U)) + 0xB3CF15E4FCDC271CULL) + aTwistOrbiterAssignSaltC[((aIndex + 29U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aScatter, 41U)) + RotL64(aCarry, 13U)) + 0x74748F4F1B37E420ULL;
            aOrbiterI = (aWandererA + RotL64(aPrevious, 13U)) + 0x01453F45B24F053FULL;
            aOrbiterJ = ((aWandererF + RotL64(aCross, 51U)) + RotL64(aCarry, 47U)) + 0x845CC14E8B9435FDULL;
            aOrbiterK = (((aWandererD + RotL64(aIngress, 3U)) + RotL64(aCarry, 35U)) + 0x938EA1C329A37376ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterA = (aWandererC + RotL64(aPrevious, 21U)) + 0x2F737C64B731A065ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x7ACA82F8203DA2C7ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x7F39378A561BB24BULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8CDFCF7B87F69295ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0x69B589CBBA93B624ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x8C9CA1A31B6A348BULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD04A11452C53ED55ULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xE4823B0DCBC514C8ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x04BC3CB998DB964AULL;
            aOrbiterG = RotL64((aOrbiterG * 0x3185AD575AE0518DULL), 37U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterA) + 0xF7CEB685829ECB02ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 20U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xDEC60E710516DBBEULL;
            aOrbiterH = RotL64((aOrbiterH * 0x95044CC6EB015BABULL), 43U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0xECCD7DBF177D74ACULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x1A2261AC4B6554C7ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x8ADE42AA75DBE6C1ULL), 27U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0xDF249F6DEE51644BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0xAAC1F5EC7DB7252EULL;
            aOrbiterI = RotL64((aOrbiterI * 0x125F32F9A4FE23EBULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x328675D4BA6F65EDULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x4129ED592F5E1A7AULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x25F9237B2D5CF3CDULL), 53U);
            //
            aIngress = RotL64(aOrbiterJ, 48U) ^ aOrbiterA;
            aIngress = aIngress + (RotL64(aOrbiterI, 11U) ^ aOrbiterG);
            aIngress = aIngress + (RotL64(aOrbiterC, 29U) ^ aOrbiterK);
            aIngress = aIngress + RotL64(aOrbiterH, 23U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aCross, 3U) + aOrbiterK) + RotL64(aOrbiterH, 5U));
            aWandererE = aWandererE + (((RotL64(aScatter, 13U) + aOrbiterH) + RotL64(aOrbiterG, 30U)) + RotL64(aCarry, 27U));
            aWandererG = aWandererG ^ ((RotL64(aIngress, 48U) + aOrbiterC) + RotL64(aOrbiterI, 57U));
            aWandererK = aWandererK + ((((RotL64(aPrevious, 19U) + RotL64(aOrbiterK, 19U)) + aOrbiterJ) + RotL64(aCarry, 51U)) + aTwistWandererUpdateSaltD[((aIndex + 19U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 57U) + RotL64(aOrbiterA, 51U)) + aOrbiterG);
