            aCross = (RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 22443U)) & S_BLOCK1], 37U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 23303U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 20194U)) & W_KEY1], 12U) ^ RotL64(aSoilLaneA[((aIndex + 20872U)) & S_BLOCK1], 27U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCarry, 23U) ^ RotL64(aIngress, 41U)) ^ (RotL64(aCross, 53U) + RotL64(aPrevious, 10U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterJ = (((aWandererE + RotL64(aCross, 4U)) + RotL64(aCarry, 37U)) + 0x0BD464F81C770D74ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 18U)) & S_SALT1];
            aOrbiterK = (aWandererG + RotL64(aIngress, 47U)) + 0x50530ADC2EC7707DULL;
            aOrbiterG = ((aWandererK + RotL64(aPrevious, 13U)) + RotL64(aCarry, 11U)) + 0xF54F7ADA4F2D8297ULL;
            aOrbiterE = (aWandererB + RotL64(aScatter, 27U)) + 0xD6186E290F47CC3BULL;
            aOrbiterA = (aWandererA + RotL64(aPrevious, 41U)) + 0x53887270D05E137DULL;
            aOrbiterB = (((aWandererI + RotL64(aScatter, 21U)) + RotL64(aCarry, 53U)) + 0x682684EC57F7C136ULL) + aKeyRotateOrbiterAssignSaltF[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterI = (aWandererC + RotL64(aIngress, 35U)) + 0x62035A46E56A6C67ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0xDA089DCE7DF12F1AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x1E6DFDF73A73139BULL;
            aOrbiterG = RotL64((aOrbiterG * 0x29D4A38A7772AD41ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x3BD644BE76B074A5ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0xA16A745094BA3C84ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x0814AE7A2222D5A1ULL), 41U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x102875EE677423F4ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 15U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0xA4A88361BF7208E2ULL) ^ aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x3CBCE7E18329E1EBULL), 47U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterE) + 0x56A607DA7BAB5BADULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterI) ^ 0x3B038DB1A7AFEAD2ULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xCAA6E9CFB3356273ULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x84C29A12DD656D22ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xA162CA2D90ED4561ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC829771FBAF0A0CFULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0x1969C0A733C1C383ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x62F9259F6EE3B884ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1D10DAC3CB960985ULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x27E0B4861D85080BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0xEE1A51030C237532ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4D9E9267A8397445ULL), 53U);
            //
            aIngress = RotL64(aOrbiterI, 23U) ^ aOrbiterE;
            aIngress = aIngress + (RotL64(aOrbiterB, 42U) ^ aOrbiterA);
            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterK, 35U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererC = aWandererC ^ ((RotL64(aCross, 20U) + RotL64(aOrbiterB, 36U)) + aOrbiterI);
            aWandererI = aWandererI + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterG, 27U)) + aOrbiterB) + RotL64(aCarry, 57U));
            aWandererA = aWandererA ^ ((RotL64(aIngress, 35U) + RotL64(aOrbiterJ, 3U)) + aOrbiterE);
            aWandererG = aWandererG + (((RotL64(aScatter, 5U) + RotL64(aOrbiterE, 53U)) + aOrbiterA) + RotL64(aCarry, 19U));
            aWandererB = aWandererB ^ (((RotL64(aCross, 13U) + RotL64(aOrbiterK, 11U)) + aOrbiterB) + aKeyRotateWandererUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererE = aWandererE + ((RotL64(aIngress, 29U) + RotL64(aOrbiterB, 19U)) + aOrbiterE);
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 41U) + aOrbiterK) + RotL64(aOrbiterA, 47U)) + aKeyRotateWandererUpdateSaltE[((aIndex + 29U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererI ^ RotL64(aWandererC, 18U));
