            //
            aCross = (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 30484U)) & S_BLOCK1], 5U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 30793U)) & S_BLOCK1], 22U));
            aCross ^= (RotL64(aWoodLaneB[((S_BLOCK1 - aIndex + 28053U)) & S_BLOCK1], 13U) ^ RotL64(aHeartLaneC[((aIndex + 29944U)) & S_BLOCK1], 51U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCarry, 36U) + RotL64(aIngress, 3U)) ^ (RotL64(aPrevious, 19U) + RotL64(aCross, 51U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterD = ((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 51U)) + 0xCAFC6B330636D2EFULL;
            aOrbiterB = (((aWandererB + RotL64(aIngress, 53U)) + RotL64(aCarry, 35U)) + 0xEA824CC647E2937DULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aScatter, 19U)) + 0x83EBE1447AD1409BULL;
            aOrbiterA = ((aWandererH + RotL64(aCross, 46U)) + 0x3CD72E66515F7CE5ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 8U)) & S_SALT1];
            aOrbiterC = (aWandererK + RotL64(aPrevious, 35U)) + 0x9860FE5BF3EE92A0ULL;
            aOrbiterK = (aWandererD + RotL64(aIngress, 5U)) + 0x2C8B54B9372A1A70ULL;
            aOrbiterF = ((aWandererC + RotL64(aCross, 11U)) + RotL64(aCarry, 11U)) + 0x4E7025089357377CULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xC4B29E571E70A96EULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0x7D8D5947F58172B7ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7B514F3E1F9C13DBULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterA) + 0x58AD7D8EA7DE9DA5ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xBEF63929A9230ED3ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE9BE971BB8409515ULL), 23U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xA706C1524F146A49ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 23U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xFD5C9BC8A461DCEAULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3014B5B1866AD035ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x8BE05C09E0A881D8ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterC) ^ 0x05D4EDF335477B75ULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x1BC7D7391E1B8F05ULL), 43U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterG) + 0x11D05159244FBDB6ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0xE4F646CE536865D5ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x627B39A84BEF0C0BULL), 57U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x875CCD18C737F7A7ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x4BE79CA711412364ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x9BB01C2B1DA2A243ULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x795C16C44C4BACFEULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x91C06AF5C55D64D4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x124DCC079604EF13ULL), 37U);
            //
            aIngress = aOrbiterA ^ RotL64(aOrbiterF, 41U);
            aIngress = aIngress + (RotL64(aOrbiterB, 23U) ^ aOrbiterG);
            aIngress = aIngress + (RotL64(aOrbiterK, 29U) ^ aOrbiterC);
            aIngress = aIngress + RotL64(aOrbiterD, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 41U) + aOrbiterB) + RotL64(aOrbiterK, 39U)) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aCross, 29U) + aOrbiterG) + RotL64(aOrbiterF, 11U)) + RotL64(aCarry, 35U));
            aWandererK = aWandererK ^ ((RotL64(aIngress, 23U) + RotL64(aOrbiterG, 18U)) + aOrbiterC);
            aWandererH = aWandererH + ((RotL64(aScatter, 58U) + aOrbiterD) + RotL64(aOrbiterF, 3U));
            aWandererE = aWandererE ^ ((RotL64(aCross, 13U) + RotL64(aOrbiterA, 27U)) + aOrbiterC);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 47U) + RotL64(aOrbiterA, 51U)) + aOrbiterB) + RotL64(aCarry, 3U)) + aKeyRotateWandererUpdateSaltC[((aIndex + 9U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aIngress, 3U) + aOrbiterF) + RotL64(aOrbiterC, 57U));
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererG, 37U));
