            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 79U)) & S_BLOCK1], 57U) ^ RotL64(aPlasmaLaneB[((S_BLOCK1 - aIndex + 1316U)) & S_BLOCK1], 43U));
            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 4997U)) & S_BLOCK1], 23U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 7240U)) & S_BLOCK1], 34U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 35U) ^ RotL64(aPrevious, 23U)) + (RotL64(aCross, 6U) ^ RotL64(aIngress, 57U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererE + RotL64(aPrevious, 47U)) + 0xD841450F4AE21DF1ULL;
            aOrbiterD = (aWandererB + RotL64(aIngress, 37U)) + 0x149EA2BA6D1595A4ULL;
            aOrbiterC = ((aWandererC + RotL64(aScatter, 60U)) + RotL64(aCarry, 47U)) + 0xA62C64BA918DB314ULL;
            aOrbiterA = (((aWandererG + RotL64(aCross, 35U)) + RotL64(aCarry, 5U)) + 0xB19A8F9DE39F65A1ULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aScatter, 13U)) + 0x60829F291B16B905ULL;
            aOrbiterH = (aWandererK + RotL64(aPrevious, 3U)) + 0x432058EE3CE4ACAEULL;
            aOrbiterB = (aWandererJ + RotL64(aCross, 22U)) + 0xA1DD7BEE705FAFEBULL;
            aOrbiterK = (aWandererD + RotL64(aIngress, 19U)) + 0xDF43DE05A125476AULL;
            aOrbiterJ = (aWandererI + RotL64(aCross, 5U)) + 0xA76D82382388691AULL;
            aOrbiterG = (((aWandererA + RotL64(aIngress, 57U)) + RotL64(aCarry, 41U)) + 0x598C48A22BE38532ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = (aWandererF + RotL64(aScatter, 27U)) + 0x3A3F0A193F66B530ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0xBB63705EC520380FULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xCE2A9131AABE204AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x8D9D449CF5AFBAD1ULL), 21U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0xC2CDA239FB565645ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x1C4E8732586ABA8AULL;
            aOrbiterF = RotL64((aOrbiterF * 0x72CDDCE29518FDC9ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0x46E1F237A4684D9FULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x5D1644E1C05137A4ULL;
