            //
            aWandererB = aWandererB + ((RotL64(aScatter, 19U) + aOrbiterB) + RotL64(aOrbiterF, 53U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 60U) + RotL64(aOrbiterJ, 21U)) + aOrbiterF) + aKeyRotateWandererUpdateSaltE[((aIndex + 5U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 47U) + RotL64(aOrbiterE, 30U)) + aOrbiterF);
