            aWandererA = aWandererA ^ ((RotL64(aPrevious, 53U) + aOrbiterD) + RotL64(aOrbiterH, 26U));
            aWandererF = aWandererF + ((RotL64(aCross, 35U) + RotL64(aOrbiterC, 5U)) + aOrbiterG);
