            aOrbiterE = (aWandererK + RotL64(aPrevious, 47U)) + 0x34D65AECAEDC287CULL;
            aOrbiterI = (((aWandererB + RotL64(aIngress, 29U)) + RotL64(aCarry, 51U)) + 0xBA0CF09A9286F727ULL) + aKeyRotateOrbiterAssignSaltD[((aIndex + 27U)) & S_SALT1];
