            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xF44B0A326B3F13BBULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x737C6F6645DA240DULL;
            aOrbiterE = RotL64((aOrbiterE * 0x3ECB304A62614C07ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x2C066F64C55D1036ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xE26569EE05DF7DC5ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF955841D0F84D84BULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x927732F4BC2C36FEULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xE31EDCC8B7C77D64ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x7AEBBA05555E4AC7ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterH) + 0x3E405B6E60383581ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x11B674338A5D2906ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x386D5AB9CC785E71ULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xEB258092C149E2C9ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x064C28D36DD901BDULL;
            aOrbiterI = RotL64((aOrbiterI * 0x1B4CABF5A633C5EBULL), 43U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0xADAB2D5E1F3222C7ULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x5F99EE12A0618B67ULL;
