            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0xC57D3AD426E72681ULL) + aKeyRotateOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x37F52461B7BAB893ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x9ABBF55ED993ECA1ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x7515259A198E4F83ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xCD8CA814B7C901CFULL;
            aOrbiterC = RotL64((aOrbiterC * 0x83F2A5886DE21D03ULL), 57U);
