            aCross ^= (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 5305U)) & S_BLOCK1], 40U) ^ RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 5404U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCross, 58U) ^ RotL64(aPrevious, 41U)) + (RotL64(aCarry, 27U) ^ RotL64(aIngress, 13U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterA = ((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 27U)) + 0xE26B372209AF235EULL;
            aOrbiterI = (aWandererH + RotL64(aIngress, 27U)) + 0xEF7680E7B5D19311ULL;
            aOrbiterE = ((aWandererB + RotL64(aScatter, 57U)) + RotL64(aCarry, 41U)) + 0x286F3BBF2C79B2E9ULL;
            aOrbiterF = ((aWandererE + RotL64(aCross, 34U)) + RotL64(aCarry, 13U)) + 0xA53C9429318748C7ULL;
            aOrbiterC = (aWandererJ + RotL64(aIngress, 51U)) + 0xC2220EE632BB3D91ULL;
            aOrbiterH = ((aWandererA + RotL64(aCross, 19U)) + 0xF718160ADE698D6AULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 22U)) & S_SALT1];
