            aIngress = (RotL64(aKineticLaneA[((aIndex + 9233U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneC[((aIndex + 5682U)) & S_BLOCK1], 3U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 5820U)) & W_KEY1], 37U) ^ RotL64(aIceLaneB[((S_BLOCK1 - aIndex + 10596U)) & S_BLOCK1], 54U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 10453U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 7708U)) & S_BLOCK1], 47U));
            aCross ^= (RotL64(aMagmaLaneB[((S_BLOCK1 - aIndex + 5512U)) & S_BLOCK1], 26U) ^ RotL64(aPlasmaLaneA[((aIndex + 7805U)) & S_BLOCK1], 5U));
