            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0xA88D2B3CBAAD276EULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 7U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x68BDCD5DBE32552EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x032D04062F9D4D13ULL), 11U);
