            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xC3C515C3AB602A30ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x76C119A06B4F022FULL) ^ aKeySpawnOrbiterUpdateSaltD[(((31U - aIndex) + 27U)) & S_SALT1];
