            //
            aOrbiterI = (aWandererF + RotL64(aScatter, 21U)) + 0x26586332A215E1E6ULL;
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 60U)) + 0xABF4CB11B1F84057ULL) + aKeySpawnOrbiterAssignSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterK = ((aWandererE + RotL64(aIngress, 5U)) + 0xA517BED87237A73FULL) + aKeySpawnOrbiterAssignSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
